import { useState } from "react";
export default function Arraystate() {
  const [devicse, setdvice] = useState("");
  const [arrdvices, setarrdvis] = useState([
    { id: 1, name: "14Pro" },
    { id: 2, name: "15Pro" },
    { id: 3, name: "16Pro" },
  ]);
  const dviselist = arrdvices.map((d) => {
    return <li>{d}</li>;
  });
  return (
    <div className="list">
      {dviselist}
      <div>
        <input
          value={devicse}
          onChange={(d) => {
            setdvice(d.target.value);
          }}
        ></input>
        <button
          onClick={() => {
            setarrdvis([...arrdvices, devicse]);
          }}
        >
          +
        </button>
      </div>
    </div>
  );
}
